//#region src/internal/screen-scale.ts
function screenScale(element) {
	if (!(element instanceof HTMLElement)) return [1, 1];
	const rect = element.getBoundingClientRect();
	const ratio = (drawn, laid) => laid && Math.abs(drawn - laid) >= 1 ? drawn / laid : 1;
	return [ratio(rect.width, element.offsetWidth), ratio(rect.height, element.offsetHeight)];
}
function layoutHeight(element) {
	return (element.getBoundingClientRect().height || 0) / screenScale(element)[1];
}
//#endregion
export { layoutHeight, screenScale };
